function firebaseAssignmentTargetLabel(a={}){const m=a.targetMode||'all',map={all:'Cả lớp',support:'Nhóm cần hỗ trợ',developing:'Nhóm đang củng cố',strong:'Nhóm khá/tốt',overdue:'Nhóm đang trễ bài',new:'Nhóm chưa đủ dữ liệu'};return map[m]||'Nhóm được chọn'}
