async function firebaseLoadClassIntelligence(classId,force=false){if(!requireTeacher('Phân tích lớp'))return;if(!firebaseUser||!firebaseDb||!classId)return null;if(!force&&firebaseTeacherDashboardCache?.classId===classId)return firebaseTeacherDashboardCache;await firebaseMigrateLegacyAssignmentsV18(classId,{silent:true});await firebaseEnsureLowReadsV19(classId,{silent:true});const cref=firebaseDb.collection('classes').doc(classId),[cls,mSnap,pSnap,assignments,stSnap,pending]=await Promise.all([cref.get(),cref.collection('members').get(),cref.collection('progress').get(),firebaseV19LoadAssignments(classId,force),firebaseStudentStatsRef(classId).get(),firebaseV19LoadSubmissionIndex(classId,{status:'submitted',force})]);if(!cls.exists)throw new Error('Lớp không còn tồn tại.');const data=firebaseBuildTeacherDashboardData({classId,classData:cls.data()||{},members:mSnap.docs.map(d=>({id:d.id,data:d.data()})),progress:pSnap.docs.map(d=>({id:d.id,data:d.data()})),assignments,studentStats:stSnap.docs.map(d=>({id:d.id,data:d.data()})),pendingSubmissions:pending});firebaseTeacherDashboardCache=data;return data}
function firebaseSmartTargetStudents(c,mode='all'){
  const students=c?.students||[];
  if(mode==='all')return students;
  if(mode==='support')return students.filter(s=>s.statusClass==='bad'||(s.avgScore!=null&&s.avgScore<5)||(s.accuracy!=null&&s.accuracy<.55));
  if(mode==='overdue')return students.filter(s=>s.overdueMissing>0);
  if(mode==='strong')return students.filter(s=>s.statusClass==='good'||((s.avgScore??0)>=8&&(s.accuracy==null||s.accuracy>=.75)));
  if(mode==='new')return students.filter(s=>s.submitted===0&&s.avgScore==null&&s.accuracy==null);
  if(mode==='developing'){const support=new Set(firebaseSmartTargetStudents(c,'support').map(x=>x.uid)),strong=new Set(firebaseSmartTargetStudents(c,'strong').map(x=>x.uid));return students.filter(s=>(s.avgScore!=null||s.accuracy!=null)&&!support.has(s.uid)&&!strong.has(s.uid))}
  return students
}
