function firebaseSetNotificationBadge(n=0){let b=document.getElementById('notificationBadge');if(!b)return;b.textContent=n>99?'99+':String(n);b.classList.toggle('show',n>0)}
function firebaseNotificationPriority(type){return {urgent:0,deadline:1,support:2,success:3,info:4}[type]??5}
function firebaseNotificationCard(n){let icon={urgent:'!',deadline:'◷',support:'◎',success:'✓',info:'i'}[n.type]||'i',actions=(n.actions||[]).map(a=>`<button class="btn ${a.primary?'btn-blue':'btn-soft'}" onclick="${a.onclick}">${esc(a.label)}</button>`).join('');return `<div class="notification-card ${n.type||'info'}"><div class="notification-icon">${icon}</div><div><h4>${esc(n.title||'Thông báo')}</h4><p>${esc(n.message||'')}</p>${actions?`<div class="notification-actions">${actions}</div>`:''}</div><div class="notification-time">${esc(n.time||'')}</div></div>`}
function renderNotificationsPage(){
  const sel=document.getElementById('notificationClassSelect'),banner=document.getElementById('notificationBanner'),list=document.getElementById('notificationList');if(!banner||!list)return;
  if(sel&&isTeacherRole()){let v=firebaseNotificationClassId||firebaseSelectedClassId||firebaseOwnedClasses?.[0]?.id||'';sel.innerHTML='<option value="">Chọn lớp</option>'+(firebaseOwnedClasses||[]).map(c=>`<option value="${attrEsc(c.id)}" ${c.id===v?'selected':''}>${esc(c.name||'Lớp học')}</option>`).join('');if(v)firebaseNotificationClassId=v}
  if(!firebaseReady){banner.className='firebase-banner error';banner.textContent='Firebase chưa sẵn sàng. Thông báo online tạm thời chưa tải được.';return}
  if(!firebaseUser){banner.className='firebase-banner warn';banner.textContent='Đăng nhập Firebase để xem thông báo theo lớp.';list.innerHTML='<div class="notification-empty">Chưa đăng nhập.</div>';firebaseSetNotificationBadge(0);return}
  banner.className='firebase-banner';banner.textContent=isTeacherRole()?'Thông báo được tính trực tiếp từ dữ liệu lớp và bài giao hiện tại.':'Thông báo được tính từ bài giáo viên giao và kết quả gần đây của em.';
  renderNotificationItems(firebaseNotificationItems||[])
}
function renderNotificationItems(items=[]){
  firebaseNotificationItems=[...items].sort((a,b)=>firebaseNotificationPriority(a.type)-firebaseNotificationPriority(b.type));let list=document.getElementById('notificationList');const count=t=>items.filter(x=>x.type===t).length,set=(id,v)=>{let e=document.getElementById(id);if(e)e.textContent=v};set('notifyMetricUrgent',count('urgent'));set('notifyMetricDeadline',count('deadline'));set('notifyMetricSupport',count('support'));set('notifyMetricTotal',items.length);if(list)list.innerHTML=items.length?firebaseNotificationItems.map(firebaseNotificationCard).join(''):'<div class="notification-empty"><b>Không có việc khẩn cấp.</b><br>Mọi thứ đang ổn hoặc chưa đủ dữ liệu để tạo thông báo.</div>';firebaseSetNotificationBadge(items.filter(x=>x.type==='urgent'||x.type==='deadline').length)
}
async function firebaseBuildStudentNotifications(){
  await firebaseRefreshStudentAssignments();const now=Date.now(),items=[];(firebaseStudentAssignments||[]).forEach(a=>{if(a.submission){if(a.submission.score==null)items.push({type:'info',title:`Đã nộp: ${a.title||'Bài được giao'}`,message:'Bài đã được khóa theo V21 và đang chờ tài khoản giáo viên chấm.',time:firebaseDateText(a.submission.submittedAt),actions:[{label:'Xem trạng thái',onclick:`firebaseShowMySubmission('${attrEsc(a.classId)}','${attrEsc(a.id)}')`}]});else if(Number(a.submission.score)<5)items.push({type:'support',title:`Cần củng cố: ${a.title||'Bài đã nộp'}`,message:`Điểm ${Number(a.submission.score).toFixed(1)}/10. Em nên luyện lại các mã kiến thức còn yếu.`,time:firebaseDateText(a.submission.submittedAt),actions:[{label:'Phân tích năng lực',onclick:`goPage('analytics')`,primary:true}]});return}let due=firebaseToDate(a.dueAt);if(!due)return;let left=due.getTime()-now;if(left<0)items.push({type:'urgent',title:`Đã quá hạn: ${a.title||'Bài được giao'}`,message:`Bài của ${a.className||'lớp học'} đã quá hạn lúc ${firebaseDateText(a.dueAt)}.`,time:'Quá hạn',actions:[{label:'Mở lớp học',onclick:`goPage('online')`}]});else if(left<=24*3600e3)items.push({type:'deadline',title:`Sắp hết hạn: ${a.title||'Bài được giao'}`,message:`Còn khoảng ${Math.max(1,Math.ceil(left/3600e3))} giờ để hoàn thành bài.`,time:firebaseDateText(a.dueAt),actions:[{label:'Làm bài ngay',onclick:`firebaseOpenAssignment('${attrEsc(a.classId)}','${attrEsc(a.id)}')`,primary:true}]});else if(left<=72*3600e3)items.push({type:'deadline',title:`Bài sắp đến hạn: ${a.title||'Bài được giao'}`,message:`Hạn nộp ${firebaseDateText(a.dueAt)}.`,time:'Trong 3 ngày',actions:[{label:'Xem bài',onclick:`goPage('online')`}]})});let weak=getSkillAnalytics().filter(x=>x.attempts>=2&&x.accuracy<.6).slice(0,2);weak.forEach(w=>items.push({type:'support',title:`Mã ${w.code} cần học lại`,message:`Độ chính xác hiện tại ${Math.round(w.accuracy*100)}% sau ${w.attempts} lượt. ${w.title||''}`,time:'Năng lực cá nhân',actions:[{label:'Luyện điểm yếu',onclick:`startAdaptivePractice(10)`,primary:true}]}));return items
}
async function firebaseBuildTeacherNotifications(classId){
  const c=await firebaseLoadClassIntelligence(classId,true),now=Date.now(),items=[];
  c.assignments.forEach(a=>{let due=firebaseToDate(a.dueAt),missing=Math.max(0,(a.total||0)-(a.submitted||0));if(!due||!missing)return;let left=due.getTime()-now;if(left<0)items.push({type:'urgent',title:`${missing} học sinh chưa nộp “${a.title||'Bài giao'}”`,message:`Bài đã quá hạn. Đối tượng: ${firebaseAssignmentTargetLabel(a)}.`,time:firebaseDateText(a.dueAt),actions:[{label:'Xem kết quả',onclick:`firebaseShowAssignmentResults('${attrEsc(classId)}','${attrEsc(a.id)}')`,primary:true},{label:'Giao bài bù nhóm trễ',onclick:`firebaseStartSmartAssignment('${attrEsc(classId)}','overdue')`}]});else if(left<=24*3600e3)items.push({type:'deadline',title:`“${a.title||'Bài giao'}” sắp hết hạn`,message:`Còn ${missing} học sinh chưa nộp; khoảng ${Math.max(1,Math.ceil(left/3600e3))} giờ còn lại.`,time:firebaseDateText(a.dueAt),actions:[{label:'Xem kết quả',onclick:`firebaseShowAssignmentResults('${attrEsc(classId)}','${attrEsc(a.id)}')`,primary:true}]})});
  const bad=c.students.filter(s=>s.statusClass==='bad');if(bad.length)items.push({type:'support',title:`${bad.length} học sinh cần hỗ trợ`,message:`Hệ thống phát hiện điểm thấp, độ chính xác thấp hoặc trễ bài. Có thể giao một đề củng cố riêng cho nhóm này.`,time:c.className,actions:[{label:'Giao bài nhóm yếu',onclick:`firebaseStartSmartAssignment('${attrEsc(classId)}','support')`,primary:true},{label:'Xem dashboard',onclick:`firebaseOpenTeacherDashboard('${attrEsc(classId)}')`}]});
  if(c.weakSkills?.length){let w=c.weakSkills[0];items.push({type:'support',title:`Cả lớp đang yếu ${w.code}`,message:`${w.title||w.code} xuất hiện trong danh sách yếu của ${w.count} học sinh${w.accuracy==null?'':`, độ chính xác TB ${Math.round(w.accuracy*100)}%`}.`,time:'Ưu tiên chuyên môn',actions:[{label:'Mở ngân hàng câu hỏi',onclick:`goPage('question-bank')`}]})}
  const groups=document.getElementById('notificationSmartGroups');if(groups){const modes=[['support','Cần hỗ trợ'],['developing','Đang củng cố'],['strong','Khá / tốt'],['overdue','Đang trễ bài'],['new','Chưa đủ dữ liệu']];groups.innerHTML=modes.map(([m,l])=>{let n=firebaseSmartTargetStudents(c,m).length;return `<div class="smart-preview-row"><div><b>${l}</b><br><small>${n}/${c.memberCount} học sinh</small></div><button class="btn btn-soft" ${n?'':'disabled'} onclick="firebaseStartSmartAssignment('${attrEsc(classId)}','${m}')">Giao bài</button></div>`}).join('')}
  const weakBox=document.getElementById('notificationWeakSkills');if(weakBox)weakBox.innerHTML=c.weakSkills?.length?c.weakSkills.slice(0,5).map(w=>`<div class="teacher-weak-row"><div class="rank">${w.count}</div><div><b>${esc(w.title||w.code)}</b><small>${esc(w.code)}${w.accuracy==null?'':` • chính xác TB ${Math.round(w.accuracy*100)}%`}</small></div></div>`).join(''):'<div class="teacher-live-empty">Chưa đủ dữ liệu.</div>';return items
}
async function firebaseRefreshNotifications(force=false){
  if(firebaseNotificationLoading)return;if(!document.getElementById('page-notifications')?.classList.contains('active')&&!force)return;renderNotificationsPage();if(!firebaseUser||!firebaseDb)return;firebaseNotificationLoading=true;document.getElementById('page-notifications')?.classList.add('notification-refreshing');try{let items;if(isTeacherRole()){let classId=firebaseNotificationClassId||firebaseSelectedClassId||firebaseOwnedClasses?.[0]?.id||'';if(!classId){firebaseNotificationItems=[];renderNotificationItems([]);let b=document.getElementById('notificationBanner');if(b){b.className='firebase-banner warn';b.textContent='Tạo hoặc chọn một lớp online để hệ thống tổng hợp thông báo.'}return}firebaseNotificationClassId=classId;items=await firebaseBuildTeacherNotifications(classId)}else items=await firebaseBuildStudentNotifications();renderNotificationItems(items)}catch(err){console.error('Notifications',err);let b=document.getElementById('notificationBanner');if(b){b.className='firebase-banner error';b.textContent=firebaseErrorText(err)}}finally{firebaseNotificationLoading=false;document.getElementById('page-notifications')?.classList.remove('notification-refreshing')}
}
